const $=(s,r=document)=>r.querySelector(s);
const escapar=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const linkSeguro=u=>{if(typeof u!=='string'||!u.trim())return'';try{const p=new URL(u,location.origin);return['http:','https:'].includes(p.protocol)?p.href:''}catch{return''}};
let bloco,lista,status,audioAtual=null,botaoAtual=null;

function montar(){const conteudo=$('#idiomas .conteudo-busca'),form=$('#form-idiomas');if(!conteudo||!form||$('#lingua-viva'))return;bloco=document.createElement('section');bloco.id='lingua-viva';bloco.className='lingua-viva';bloco.innerHTML=`<header><div><span class="rotulo">VOZES DOCUMENTADAS · NÃO SINTÉTICAS</span><h3>Ouça uma língua <em>viva.</em></h3><p>Quando a fonte oferece gravação humana, a Biblioteca aproxima voz, transcrição, tradução e material de estudo no mesmo lugar.</p></div><div class="lingua-viva-selo">Tatoeba · Lingua Libre</div></header><div id="status-lingua-viva" class="status-lingua-viva">Pesquise um idioma para procurar gravações humanas documentadas.</div><div id="lista-lingua-viva" class="lista-lingua-viva"></div><footer><span>Os áudios permanecem hospedados nas fontes originais.</span><a href="https://commonvoice.mozilla.org/datasets" target="_blank" rel="noopener noreferrer">Explorar Mozilla Common Voice ↗</a></footer>`;form.after(bloco);lista=$('#lista-lingua-viva');status=$('#status-lingua-viva');form.addEventListener('submit',()=>setTimeout(()=>buscar($('#campo-idiomas')?.value),0));document.addEventListener('click',controlarPlayer);document.addEventListener('keydown',e=>{if(e.key==='Escape')parar()})}
function tempo(s){if(!Number.isFinite(s))return'0:00';const m=Math.floor(s/60),r=Math.floor(s%60);return`${m}:${String(r).padStart(2,'0')}`}
function parar(){if(audioAtual){audioAtual.pause();audioAtual.currentTime=0}if(botaoAtual){botaoAtual.textContent='▶';botaoAtual.setAttribute('aria-label','Reproduzir gravação')}audioAtual=botaoAtual=null}
function controlarPlayer(e){const b=e.target.closest('[data-audio-vivo]');if(!b)return;const src=linkSeguro(b.dataset.audioVivo);if(!src)return;if(botaoAtual===b&&audioAtual){if(audioAtual.paused){audioAtual.play().catch(()=>{});b.textContent='Ⅱ';b.setAttribute('aria-label','Pausar gravação')}else{audioAtual.pause();b.textContent='▶';b.setAttribute('aria-label','Reproduzir gravação')}return}parar();const a=new Audio(src);audioAtual=a;botaoAtual=b;b.textContent='Ⅱ';b.setAttribute('aria-label','Pausar gravação');const card=b.closest('.voz-card'),barra=card?.querySelector('i'),relogio=card?.querySelector('[data-tempo]');a.addEventListener('timeupdate',()=>{if(barra&&a.duration)barra.style.width=`${Math.min(100,(a.currentTime/a.duration)*100)}%`;if(relogio)relogio.textContent=`${tempo(a.currentTime)} / ${tempo(a.duration)}`});a.addEventListener('ended',()=>{if(barra)barra.style.width='0%';if(relogio)relogio.textContent='0:00';b.textContent='▶';audioAtual=botaoAtual=null});a.play().catch(()=>{b.textContent='▶';status.textContent='A fonte bloqueou a reprodução direta deste arquivo. Use “abrir fonte” no cartão.'})}
function traducao(item){const d=String(item.descricao||'').trim();if(!d||/^Pronúncia\s*·/i.test(d))return'Tradução não informada por esta fonte.';return d}
function render(itens,q){if(!itens.length){status.textContent=`Nenhuma gravação humana direta apareceu para “${q}” nesta tentativa.`;lista.innerHTML='<div class="voz-vazio"><strong>A língua continua pesquisável.</strong><span>Os materiais escritos, dicionários, gramáticas e arquivos seguem aparecendo logo abaixo.</span></div>';return}status.textContent=`${itens.length} ${itens.length===1?'gravação humana encontrada':'gravações humanas encontradas'} para ouvir sem sair da biblioteca.`;lista.innerHTML=itens.slice(0,8).map((x,i)=>{const audio=linkSeguro(x.audio),url=linkSeguro(x.url);return`<article class="voz-card"><div class="voz-numero">${String(i+1).padStart(2,'0')}</div><div class="voz-texto"><span>${escapar(x.idioma||'Idioma documentado')}</span><h4>${escapar(x.titulo||'Gravação')}</h4><p>${escapar(traducao(x))}</p><small>${escapar(x.provedor||'Fonte linguística')}</small></div><div class="voz-player"><button type="button" data-audio-vivo="${escapar(audio)}" aria-label="Reproduzir gravação">▶</button><div class="voz-faixa"><span><i></i></span><small data-tempo>0:00</small></div>${url?`<a href="${escapar(url)}" target="_blank" rel="noopener noreferrer">abrir fonte ↗</a>`:''}</div></article>`}).join('')}
async function buscar(q){q=String(q||'').trim();parar();if(!q){status.textContent='Pesquise um idioma para procurar gravações humanas documentadas.';lista.innerHTML='';return}status.textContent=`Procurando vozes humanas documentadas para “${q}”…`;lista.innerHTML='<div class="voz-vazio"><strong>Escutando os arquivos.</strong><span>Tatoeba e Lingua Libre são consultados junto com as demais fontes da área de idiomas.</span></div>';try{const r=await fetch(`/api/idiomas?q=${encodeURIComponent(q)}`,{headers:{Accept:'application/json'}});if(!r.ok)throw Error();const d=await r.json(),itens=(Array.isArray(d?.resultados)?d.resultados:[]).filter(x=>linkSeguro(x.audio));render(itens,q)}catch{status.textContent='As fontes de áudio não responderam nesta tentativa.';lista.innerHTML=''}}

montar();
window.BibliotecaLinguaViva={buscar};
